// Test with default save mode and additional fcc.
add_task(async function test_default_with_additional_fcc() {
  await runTest({
    mode: null,
    config: {
      mode: "draft",
      fcc: ["Drafts", "Fcc"],
    },
    // Since Bug 279366 the additional fcc folder is ignored while saving drafts.
    expected: {
      mode: "draft",
      fcc: ["Drafts"],
    },
  });
});
